// Reasons are the google.rpc.ErrorInfo reasons the generated servers return.
// They are part of the API: branch on them, never on a message.
const (
	ReasonNotFound               = "NOT_FOUND"
	ReasonAlreadyExists          = "ALREADY_EXISTS"
	ReasonConcurrentModification = "CONCURRENT_MODIFICATION"
	ReasonRequiredField          = "REQUIRED_FIELD"
	ReasonInvalidID              = "INVALID_ID"
	ReasonMalformedName          = "MALFORMED_NAME"
	ReasonUnknownMaskPath        = "UNKNOWN_MASK_PATH"
	ReasonNothingToUpdate        = "NOTHING_TO_UPDATE"
	ReasonImmutableField         = "IMMUTABLE_FIELD"
	ReasonInvalidArgument        = "INVALID_ARGUMENT"
	ReasonInvalidState           = "INVALID_STATE"
)

// Op is the write a Validate or ParentCheck hook is asked about.
type Op int

// The operations hooks see.
const (
	OpCreate Op = iota + 1
	OpUpdate
	OpList
)

func (o Op) String() string {
	switch o {
	case OpCreate:
		return "create"
	case OpUpdate:
		return "update"
	case OpList:
		return "list"
	}
	return "unknown"
}

// ErrFailedPrecondition is the sentinel of a call the state of a resource
// forbids (FAILED_PRECONDITION, reason INVALID_STATE unless a Problem names
// another). The repository sentinels cover the other standard codes.
var ErrFailedPrecondition = errors.New("failed precondition")

// Kinds bind the repository sentinels, and ErrFailedPrecondition, to their
// status codes and default reasons. NewTranslator registers them; a consumer
// building a problem.Translator of its own registers them beside its kinds.
func Kinds() []problem.Kind {
	return []problem.Kind{
		{Err: repox.ErrNotFound, Code: codes.NotFound, Reason: ReasonNotFound},
		{Err: repox.ErrAlreadyExists, Code: codes.AlreadyExists, Reason: ReasonAlreadyExists},
		{Err: repox.ErrConflict, Code: codes.Aborted, Reason: ReasonConcurrentModification},
		{Err: repox.ErrInvalidArgument, Code: codes.InvalidArgument, Reason: ReasonInvalidArgument},
		{Err: ErrFailedPrecondition, Code: codes.FailedPrecondition, Reason: ReasonInvalidState},
		{Err: context.Canceled, Code: codes.Canceled, Reason: "CANCELLED"},
		{Err: context.DeadlineExceeded, Code: codes.DeadlineExceeded, Reason: "DEADLINE_EXCEEDED"},
	}
}

// Reasons are the reasons the generated servers return, for the
// translator's declarations and an API's error reference.
func Reasons() []problem.Reason {
	return []problem.Reason{
		{Name: ReasonNotFound, Code: codes.NotFound, Description: "The resource named does not exist, or is deleted."},
		{Name: ReasonAlreadyExists, Code: codes.AlreadyExists, Description: "A create's id is taken, or an Undelete names something not deleted."},
		{Name: ReasonConcurrentModification, Code: codes.Aborted, Description: "The etag sent is no longer current, or another writer won the race for the same record."},
		{Name: ReasonRequiredField, Code: codes.InvalidArgument, Description: "A field the call needs is empty."},
		{Name: ReasonInvalidID, Code: codes.InvalidArgument, Description: "A *_id is not a valid AIP-122 id."},
		{Name: ReasonMalformedName, Code: codes.InvalidArgument, Description: "A resource name is not shaped like the collection it should be in."},
		{Name: ReasonUnknownMaskPath, Code: codes.InvalidArgument, Description: "update_mask names a field the resource does not have."},
		{Name: ReasonNothingToUpdate, Code: codes.InvalidArgument, Description: "An update sets no field and names none in update_mask."},
		{Name: ReasonImmutableField, Code: codes.InvalidArgument, Description: "An update changes a field that cannot change once set."},
		{Name: ReasonInvalidArgument, Code: codes.InvalidArgument, Description: "The request is wrong in a way no more specific reason names."},
		{Name: ReasonInvalidState, Code: codes.FailedPrecondition, Description: "The resource's state forbids the call, in a way no more specific reason names."},
	}
}

// NewTranslator is the problem.Translator the generated servers use when
// given none: kinds first (a consumer's own sentinels), then Kinds(), with
// Reasons() declared and the repositories' reference errors rendered in the
// store's own domain.
func NewTranslator(domain string, kinds ...problem.Kind) *problem.Translator {
	return problem.New(domain, append(kinds, Kinds()...)...).
		Declare(Reasons()...).
		Handle(ReferenceStatus)
}

// ReferenceStatus renders a repository reference integrity error:
// FAILED_PRECONDITION with an ErrorInfo in the store's domain
// (FOREIGN_KEY_VIOLATION, REFERENCE_NOT_FOUND, RESOURCE_REFERENCED). It is a
// problem.Translator handler.
func ReferenceStatus(err error) (error, bool) {
	var e *repox.ReferenceError
	if !errors.As(err, &e) {
		return nil, false
	}
	reason := e.Reason()
	msg := problem.Sentence(e.Error())
	if reason == repox.ReasonForeignKey {
		msg = "The write names a resource that does not exist, or removes one that something still refers to"
		if e.Constraint != "" {
			msg += " (constraint " + e.Constraint + ")"
		}
		msg = problem.Sentence(msg + "; create the referenced resource first, or remove what refers to it")
	}
	metadata := map[string]string{}
	for k, v := range map[string]string{"constraint": e.Constraint, "field": e.Field, "resource_type": e.ResourceType, "resource_name": e.Name} {
		if v != "" {
			metadata[k] = v
		}
	}
	st := status.New(codes.FailedPrecondition, msg)
	details := []protoadapt.MessageV1{&errdetails.ErrorInfo{Reason: reason, Domain: repox.ErrorDomain, Metadata: metadata}}
	if e.Name != "" {
		details = append(details, &errdetails.PreconditionFailure{Violations: []*errdetails.PreconditionFailure_Violation{
			{Type: reason, Subject: e.Name, Description: msg},
		}})
	}
	if detailed, derr := st.WithDetails(details...); derr == nil {
		return detailed.Err(), true
	}
	return st.Err(), true
}

// Options configure a generated server. New<Service>Server fills the
// translator from the proto's domain unless an Option replaces it.
type Options struct {
	// Translator renders every error a handler or hook returns as a gRPC
	// status (AIP-193). Hooks return *problem.Problem values, errors wrapping
	// a registered sentinel, or statuses.
	Translator *problem.Translator
	// Trace wraps every handler body: a span, request counters, outcome logs.
	// Nil runs the body as it is.
	Trace func(ctx context.Context, service, method string, fn func(context.Context) error) error
}

// Option sets one of Options.
type Option func(*Options)

// WithTranslator sets Options.Translator. Build it with NewTranslator (or
// register Kinds() and ReferenceStatus on your own) so the repository errors
// keep their codes.
func WithTranslator(t *problem.Translator) Option { return func(o *Options) { o.Translator = t } }

// WithTracer sets Options.Trace.
func WithTracer(f func(ctx context.Context, service, method string, fn func(context.Context) error) error) Option {
	return func(o *Options) { o.Trace = f }
}

// Apply returns defaults with opts applied.
func Apply(defaults Options, opts []Option) Options {
	for _, opt := range opts {
		opt(&defaults)
	}
	return defaults
}

// Run runs one handler body: traced, with whatever it returns rendered as a
// gRPC status.
func (o Options) Run(ctx context.Context, service, method string, fn func(context.Context) error) error {
	body := func(ctx context.Context) error { return o.Status(fn(ctx)) }
	if o.Trace == nil {
		return body(ctx)
	}
	return o.Trace(ctx, service, method, body)
}

// Status renders err with the translator.
func (o Options) Status(err error) error {
	if err == nil {
		return nil
	}
	return o.Translator.ToStatus(err)
}

// BadField is an INVALID_ARGUMENT naming the request field at fault.
func BadField(reason, field, what, fix string) *problem.Problem {
	return &problem.Problem{Kind: repox.ErrInvalidArgument, Reason: reason, Field: field, What: what, Fix: fix}
}

// Missing is a NOT_FOUND naming the resource that does not exist.
func Missing(reason, resourceType, name, what, fix string) *problem.Problem {
	return &problem.Problem{Kind: repox.ErrNotFound, Reason: reason, ResourceType: resourceType, ResourceName: name, What: what, Fix: fix}
}

// Blocked is a FAILED_PRECONDITION: the state of the named resource forbids
// the call.
func Blocked(reason, resourceType, name, what, fix string) *problem.Problem {
	return &problem.Problem{Kind: ErrFailedPrecondition, Reason: reason, ResourceType: resourceType, ResourceName: name, What: what, Fix: fix}
}

// NotFoundAs restates a repository ErrNotFound as a NOT_FOUND naming the
// resource; any other error is returned as it is.
func NotFoundAs(err error, resourceType, name string) error {
	if err == nil || !errors.Is(err, repox.ErrNotFound) {
		return err
	}
	var p *problem.Problem
	if errors.As(err, &p) {
		return err
	}
	return Missing(ReasonNotFound, resourceType, name,
		fmt.Sprintf("%s does not exist, or is deleted", quoteName(name)),
		"Check the name, or list what exists")
}

// AlreadyExistsAs restates a repository ErrAlreadyExists as an ALREADY_EXISTS
// naming the resource; any other error is returned as it is.
func AlreadyExistsAs(err error, resourceType, name, fix string) error {
	if err == nil || !errors.Is(err, repox.ErrAlreadyExists) {
		return err
	}
	var p *problem.Problem
	if errors.As(err, &p) {
		return err
	}
	return &problem.Problem{Kind: repox.ErrAlreadyExists, Reason: ReasonAlreadyExists, ResourceType: resourceType, ResourceName: name,
		What: fmt.Sprintf("%s already exists", quoteName(name)), Fix: fix}
}

func quoteName(name string) string {
	if name == "" {
		return "the resource"
	}
	return fmt.Sprintf("%q", name)
}

// IsNotFound reports a missing resource, as a repository sentinel or a status.
func IsNotFound(err error) bool {
	return errors.Is(err, repox.ErrNotFound) || status.Code(err) == codes.NotFound
}

// resourceID is AIP-122's rule for a caller-chosen id: lower-case letters,
// digits and hyphens, starting with a letter, at most 63 characters.
var resourceID = regexp.MustCompile(`^[a-z]([a-z0-9-]{0,61}[a-z0-9])?$`)

// CheckID accepts an empty id (the repository mints one) or a valid AIP-122
// id, and refuses anything else with INVALID_ID.
func CheckID(field, id string) error {
	if id == "" || resourceID.MatchString(id) {
		return nil
	}
	return BadField(ReasonInvalidID, field, fmt.Sprintf("%s %q is not a valid id", field, id),
		"An id is lower-case letters, digits and hyphens, starts with a letter, ends with a letter or digit and is at most 63 characters (AIP-122); or leave it empty to have one assigned")
}

// CheckName refuses, with REQUIRED_FIELD or MALFORMED_NAME, a name not shaped
// collection/{id}/... over collections. wildcard admits AIP-159's "-" for an
// id, as a List parent may use.
func CheckName(field, name string, wildcard bool, collections ...string) error {
	if name == "" {
		return BadField(ReasonRequiredField, field, fmt.Sprintf("%s is required", field), "Set it and send the request again")
	}
	parts := strings.Split(name, "/")
	ok := len(parts) == 2*len(collections)
	for i := 0; ok && i < len(collections); i++ {
		id := parts[2*i+1]
		ok = parts[2*i] == collections[i] && id != "" && (wildcard || id != "-")
	}
	if ok {
		return nil
	}
	var want []string
	for _, c := range collections {
		want = append(want, c+"/{id}")
	}
	return BadField(ReasonMalformedName, field,
		fmt.Sprintf("%s must be a resource name like %s; got %q", field, strings.Join(want, "/"), name),
		"Send the full name the create call returned")
}

// Required refuses m, under the request field that carries it, when a field
// the proto marks REQUIRED (AIP-203) is unset, naming every such field at
// once so a caller fixes them in one round trip.
func Required(m proto.Message, prefix string, fields []string) error {
	r := m.ProtoReflect()
	var missing []string
	for _, name := range fields {
		fd := r.Descriptor().Fields().ByName(protoreflect.Name(name))
		if fd != nil && !r.Has(fd) {
			missing = append(missing, prefix+"."+name)
		}
	}
	switch len(missing) {
	case 0:
		return nil
	case 1:
		return BadField(ReasonRequiredField, missing[0], fmt.Sprintf("%s is required", missing[0]), "Set it and send the request again")
	}
	return BadField(ReasonRequiredField, missing[0], fmt.Sprintf("%s are required", strings.Join(missing, ", ")), "Set each of them and send the request again")
}

// ClearOutputOnly clears the named OUTPUT_ONLY fields of m, so a client
// cannot set a create_time, an etag or a delete_time by sending one.
func ClearOutputOnly(m proto.Message, fields []string) {
	r := m.ProtoReflect()
	for _, name := range fields {
		if fd := r.Descriptor().Fields().ByName(protoreflect.Name(name)); fd != nil {
			r.Clear(fd)
		}
	}
}

// UpdatePaths resolves an AIP-134 update mask against m, the resource carried
// in the request field field.
//
// "*" replaces every mutable field, which the repositories spell as an empty
// mask. An absent mask means the fields the caller populated, less name and
// the OUTPUT_ONLY ones; when that is nothing the update is refused with
// NOTHING_TO_UPDATE. A path may be a proto name or, as REST clients send it,
// a JSON name (AIP-161). A path naming no field of m is refused with
// UNKNOWN_MASK_PATH rather than silently ignored. OUTPUT_ONLY paths are
// dropped (AIP-203).
func UpdatePaths(m proto.Message, mask *fieldmaskpb.FieldMask, field string, outputOnly []string) ([]string, error) {
	desc := m.ProtoReflect().Descriptor()
	if mask == nil {
		var paths []string
		m.ProtoReflect().Range(func(fd protoreflect.FieldDescriptor, _ protoreflect.Value) bool {
			if n := string(fd.Name()); n != "name" && !slices.Contains(outputOnly, n) {
				paths = append(paths, n)
			}
			return true
		})
		if len(paths) == 0 {
			return nil, BadField(ReasonNothingToUpdate, "update_mask",
				"the request changes nothing: it sets no field of "+field+" and names none in update_mask",
				"Set the fields to change and name them in update_mask, or send update_mask=* to replace every field")
		}
		slices.Sort(paths)
		return paths, nil
	}
	if len(mask.GetPaths()) == 1 && mask.GetPaths()[0] == "*" {
		return nil, nil
	}
	fields := desc.Fields()
	var paths []string
	for _, p := range mask.GetPaths() {
		head, rest, _ := strings.Cut(p, ".")
		if fd := fields.ByJSONName(head); fd != nil && fields.ByName(protoreflect.Name(head)) == nil {
			head = string(fd.Name())
		}
		if slices.Contains(outputOnly, head) {
			continue
		}
		if rest != "" {
			head += "." + rest
		}
		paths = append(paths, head)
	}
	if !(&fieldmaskpb.FieldMask{Paths: paths}).IsValid(m) {
		return nil, BadField(ReasonUnknownMaskPath, "update_mask",
			fmt.Sprintf("update_mask %v names a field %s does not have", mask.GetPaths(), desc.Name()),
			"Name fields by their proto names (display_name, or displayName from JSON), or send * to replace every field")
	}
	if len(paths) == 0 {
		return nil, BadField(ReasonNothingToUpdate, "update_mask",
			fmt.Sprintf("update_mask %v names only fields the server sets, so the request changes nothing", mask.GetPaths()),
			"Name the fields to change")
	}
	return paths, nil
}

// Touches reports whether paths selects field: an empty mask selects every
// field, a path selects its field and every field under it.
func Touches(paths []string, field string) bool {
	if len(paths) == 0 {
		return true
	}
	for _, p := range paths {
		if p == field || strings.HasPrefix(p, field+".") || strings.HasPrefix(field, p+".") {
			return true
		}
	}
	return false
}

// TouchesAny reports whether paths selects any of fields.
func TouchesAny(paths, fields []string) bool {
	for _, f := range fields {
		if Touches(paths, f) {
			return true
		}
	}
	return false
}

// CheckImmutable refuses, with IMMUTABLE_FIELD, an update whose mask selects
// an IMMUTABLE field (AIP-203) to a value other than the stored one. Sending
// the stored value back is allowed, so a read-modify-write with "*" works.
func CheckImmutable(prefix string, existing, in proto.Message, paths, immutable []string) error {
	er, ir := existing.ProtoReflect(), in.ProtoReflect()
	for _, name := range immutable {
		if !Touches(paths, name) {
			continue
		}
		fd := er.Descriptor().Fields().ByName(protoreflect.Name(name))
		if fd == nil {
			continue
		}
		if !er.Get(fd).Equal(ir.Get(fd)) {
			return BadField(ReasonImmutableField, prefix+"."+name, fmt.Sprintf("%s.%s cannot change once set", prefix, name),
				"Leave it out of update_mask, or create a new resource")
		}
	}
	return nil
}

// CheckEtag refuses, with ABORTED CONCURRENT_MODIFICATION, a request etag
// that is not the stored one. An empty want checks nothing.
func CheckEtag(resourceType, name, want, have string) error {
	if want == "" || want == have {
		return nil
	}
	return &problem.Problem{Kind: repox.ErrConflict, Reason: ReasonConcurrentModification, ResourceType: resourceType, ResourceName: name,
		What: fmt.Sprintf("the etag sent is not the current etag of %q", name),
		Fix:  "Read it again, reapply the change and retry with the etag it returns"}
}

// Merge copies the fields of src that paths selects onto dst, every
// populated top-level field for an empty mask: the preview a validate_only
// update returns.
func Merge(dst, src proto.Message, paths []string) {
	d, s := dst.ProtoReflect(), src.ProtoReflect()
	fields := s.Descriptor().Fields()
	for i := 0; i < fields.Len(); i++ {
		fd := fields.Get(i)
		if string(fd.Name()) == "name" || !Touches(paths, string(fd.Name())) {
			continue
		}
		if s.Has(fd) {
			d.Set(fd, s.Get(fd))
		} else {
			d.Clear(fd)
		}
	}
}

// ParentOf is the parent of a resource name: "calendars/c/events/e" is
// "calendars/c", and a top-level name has none ("").
func ParentOf(name string) string {
	parts := strings.Split(name, "/")
	if len(parts) < 4 {
		return ""
	}
	return strings.Join(parts[:len(parts)-2], "/")
}

// IDOf is the last id of a resource name.
func IDOf(name string) string {
	if i := strings.LastIndex(name, "/"); i >= 0 {
		return name[i+1:]
	}
	return name
}
